// This file is generated by AI.

// 全局音频单例的测试。
//
// 硬约束是「**任意时刻只有一个在响**」, 模块级单例是这条约束的落点。
//
// 不引入 jsdom: 只给 `Audio` 一个记录调用的替身, 走真实代码路径。

import { beforeEach, describe, expect, it, vi } from 'vitest';

import { playAudio, playingKey, stopAudio, subscribeAudio, toggleAudio } from '../src/lib/audio';

/** 记录"创建了几个 Audio、各自被 pause/load 了几次"。 */
function installFakeAudio() {
  const created: Array<{
    src: string;
    paused: number;
    loaded: number;
    play: () => Promise<void>;
    emit: (type: string) => void;
  }> = [];

  class FakeAudio {
    paused = 0;
    loaded = 0;
    private readonly listeners = new Map<string, Array<() => void>>();

    constructor(public src: string) {
      created.push(this as never);
    }

    addEventListener(type: string, listener: () => void) {
      const list = this.listeners.get(type) ?? [];
      list.push(listener);
      this.listeners.set(type, list);
    }

    /** 让测试手动触发 ended / error */
    emit(type: string) {
      for (const listener of this.listeners.get(type) ?? []) listener();
    }

    play() {
      return Promise.resolve();
    }

    pause() {
      this.paused += 1;
    }

    removeAttribute() {
      this.src = '';
    }

    load() {
      this.loaded += 1;
    }
  }

  vi.stubGlobal('Audio', FakeAudio);
  return created;
}

describe('音频单例', () => {
  let created: ReturnType<typeof installFakeAudio>;

  beforeEach(() => {
    stopAudio(); // 模块级状态跨用例存活, 先清干净
    created = installFakeAudio();
  });

  it('播新的会停掉上一个（只有一个在响）', () => {
    playAudio('a.wav', 'a');
    playAudio('b.wav', 'b');

    expect(created).toHaveLength(2);
    // 第一个必须被暂停并释放, 否则它会继续响
    expect(created[0]!.paused).toBe(1);
    expect(created[0]!.loaded).toBe(1);
    expect(playingKey()).toBe('b');
  });

  it('playAudio 之后 playingKey 是新的那个', () => {
    playAudio('a.wav', 'a');
    expect(playingKey()).toBe('a');
  });

  it('stopAudio 清空当前音源', () => {
    playAudio('a.wav', 'a');
    stopAudio();

    expect(playingKey()).toBeNull();
    expect(created[0]!.paused).toBe(1);
  });

  it('没有在播时 stopAudio 是无操作', () => {
    expect(() => stopAudio()).not.toThrow();
    expect(playingKey()).toBeNull();
  });

  it('toggleAudio 对同一个 key 是停、对不同 key 是换', () => {
    toggleAudio('a.wav', 'a');
    expect(playingKey()).toBe('a');

    // 同一个 key: 停
    toggleAudio('a.wav', 'a');
    expect(playingKey()).toBeNull();

    // 不同 key: 播
    toggleAudio('b.wav', 'b');
    expect(playingKey()).toBe('b');
  });

  it('播完自动复位（界面不会一直显示"正在播放"）', () => {
    playAudio('a.wav', 'a');
    created[0]!.emit('ended');

    expect(playingKey()).toBeNull();
  });

  it('解码失败也复位，不会卡在播放中', () => {
    playAudio('a.wav', 'a');
    created[0]!.emit('error');

    expect(playingKey()).toBeNull();
  });

  it('订阅者会收到每一次变化', () => {
    const seen: Array<string | null> = [];
    const unsubscribe = subscribeAudio((key) => seen.push(key));

    playAudio('a.wav', 'a');
    playAudio('b.wav', 'b');
    stopAudio();

    // 播 b 之前必须先停 a, 所以中间会经过一次 null —— 这是"只有一个在响"的直接体现
    expect(seen).toEqual(['a', null, 'b', null]);
    unsubscribe();
  });

  it('本来就没在播时 stopAudio 不打扰订阅者', () => {
    const seen: Array<string | null> = [];
    const unsubscribe = subscribeAudio((key) => seen.push(key));

    // playAudio 内部会先调 stopAudio; 若它无条件广播, 每次播放都会多推一次无意义的 null
    playAudio('a.wav', 'a');

    expect(seen).toEqual(['a']);
    unsubscribe();
  });

  it('取消订阅后不再收到通知', () => {
    const seen: Array<string | null> = [];
    const unsubscribe = subscribeAudio((key) => seen.push(key));
    unsubscribe();

    playAudio('a.wav', 'a');

    expect(seen).toEqual([]);
  });

  it('旧的音源播完不会把新的那个也停掉', () => {
    playAudio('a.wav', 'a');
    const first = created[0]!;
    playAudio('b.wav', 'b');

    // a 被停掉时它的 ended 可能随后到达 —— 那不该影响 b
    first.emit('ended');

    expect(playingKey()).toBe('b');
  });

  it('playAudio 返回的 stop 只停自己那一个', () => {
    const stopFirst = playAudio('a.wav', 'a');
    playAudio('b.wav', 'b');

    // a 已经被 b 顶掉了, 此时再调它的 stop 不该动到 b
    stopFirst();

    expect(playingKey()).toBe('b');
  });
});
